mapper.sql:
p.PRV_PRF_USE_YN = 'Y' AND u.USR_USE_YN = 'Y' AND u.USR_STATUS_CD = 'USRC0001' AND EXISTS ( SELECT 1 FROM PROVIDER_CATEGORY_PERMISSION permission JOIN CATEGORY category ON category.CAT_SN = permission.CAT_SN AND category.CAT_DOMAIN_CD = 'CATC0002' AND category.CAT_USE_YN = 'Y' WHERE permission.USR_SN = p.USR_SN AND permission.PRV_CAT_PRM_STATUS_CD = 'PRVC0006' AND permission.PRV_CAT_PRM_USE_YN = 'Y'
AND category.CAT_SN = #{categorySn}
)
AND ( u.USR_NM LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR p.PRV_PRF_INTRO_CN LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' )
AND p.PRV_PRF_AREA_NM LIKE CONCAT('%', #{region}, '%') ESCAPE '!'

mapper.select:
SELECT permission.USR_SN, category.CAT_SN, category.CAT_NM FROM PROVIDER_CATEGORY_PERMISSION permission JOIN CATEGORY category ON category.CAT_SN = permission.CAT_SN AND category.CAT_DOMAIN_CD = 'CATC0002' AND category.CAT_USE_YN = 'Y' WHERE permission.PRV_CAT_PRM_STATUS_CD = 'PRVC0006' AND permission.PRV_CAT_PRM_USE_YN = 'Y' AND permission.USR_SN IN
#{providerUserSn}
ORDER BY permission.USR_SN, category.CAT_SORT_NO, category.CAT_SN
